import axios from 'axios';

const API_URL = 'https://localhost:7285/api';

const axiosInstance = axios.create({
    baseURL: API_URL,
    headers: {
        'Content-Type': 'application/json'
    },
    timeout: 10000,
    validateStatus: function (status) {
        return status >= 200 && status < 500;
    }
});

axiosInstance.interceptors.response.use(
    response => response.data,
    error => {
        console.error('API Hatası:', {
            message: error.message,
            status: error.response?.status,
            data: error.response?.data
        });
        
        if (error.code === 'ECONNABORTED') {
            return Promise.reject({ 
                success: false, 
                message: 'İstek zaman aşımına uğradı. Lütfen tekrar deneyin.' 
            });
        }
        
        if (!error.response) {
            return Promise.reject({ 
                success: false, 
                message: 'Sunucuya bağlanılamıyor. Lütfen internet bağlantınızı kontrol edin.' 
            });
        }

        return Promise.reject(error.response.data || { 
            success: false, 
            message: 'Bir hata oluştu' 
        });
    }
);

export const getAllStocks = async () => {
    try {
        return await axiosInstance.get('/Store2/StockGetAll');
    } catch (error) {
        console.error('Store2 - Stok verileri alınırken hata:', error);
        throw error;
    }
};

export const getCategoryStocks = async () => {
    try {
        return await axiosInstance.get('/Store2/CategoryStock');
    } catch (error) {
        console.error('Store2 - Kategori stok verileri alınırken hata:', error);
        throw error;
    }
};

export const getAllSales = async () => {
    try {
        return await axiosInstance.get('/Store2/SaleGetAll');
    } catch (error) {
        console.error('Store2 - Satış verileri alınırken hata:', error);
        throw error;
    }
};

export const createStock = async (stockData) => {
    try {
        return await axiosInstance.post('/Store2/StockCreate', stockData);
    } catch (error) {
        console.error('Store2 - Stok oluşturulurken hata:', error);
        throw error;
    }
};

export const updateStock = async (stockData) => {
    try {
        return await axiosInstance.put('/Store2/StockUpdate', stockData);
    } catch (error) {
        console.error('Store2 - Stok güncellenirken hata:', error);
        throw error;
    }
};

export const createSale = async (saleData) => {
    try {
        return await axiosInstance.post('/Store2/SaleCreate', saleData);
    } catch (error) {
        console.error('Store2 - Satış oluşturulurken hata:', error);
        throw error;
    }
};

export const createReturn = async (returnData) => {
    try {
        return await axiosInstance.post('/Store2/ReturnCreate', returnData);
    } catch (error) {
        console.error('Store2 - İade oluşturulurken hata:', error);
        throw error;
    }
};
